export type Topic = { id: number; mechanism: Text; interpretation: Text; question: Text; task: Text; terms: [Text, Text]; sources: string[]; materials: string[] };
export const topics: Topic[] = [
{ id: 2, sources: ['cns'], materials: ['СРОП 1', 'Рабочая тетрадь СРОП №1', 'English workbook ISWRT №1', 'Лекция 1', 'ПЗ 3'],
mechanism: t('Метод исследования выбирают по вопросу: ЭЭГ регистрирует суммарную электрическую активность через электроды на коже головы, вызванные потенциалы выделяют ответ, связанный со стимулом, а структурная визуализация показывает анатомию. Эти данные описывают разные стороны работы ЦНС.', 'Choose a method for the question: EEG records summed electrical activity through scalp electrodes, evoked potentials identify a stimulus-related response, and structural imaging shows anatomy. These measurements describe different aspects of CNS function.', 'Зерттеу әдісі сұраққа сай таңдалады: ЭЭГ бас терісіндегі электродтар арқылы жиынтық электр белсенділігін тіркейді, шақырылған потенциалдар тітіркендіргішке байланысты жауапты бөліп көрсетеді, ал құрылымдық бейнелеу анатомияны көрсетеді.'),
interpretation: t('На ЭЭГ влияют состояние бодрствования, монтаж электродов, движения и другие артефакты. Один ритм не определяет диагноз или интеллект. Исторический эксперимент с повреждением помогает обсуждать причинность, но его вывод ограничен видом, условиями и взаимодействием сетей.', 'EEG depends on arousal, electrode montage, movement and other artifacts. One rhythm does not establish a diagnosis or intelligence. Historical lesion experiments inform causal reasoning, but their conclusions depend on species, conditions and network interactions.', 'ЭЭГ-ге сергектік күйі, электродтардың орналасуы, қозғалыс және басқа артефактілер әсер етеді. Бір ырғақ диагнозды немесе интеллектіні анықтамайды. Зақымдау тәжірибесінің қорытындысы түрге, жағдайға және желілердің байланысына тәуелді.'),
question: t('Чем спонтанная ЭЭГ отличается от вызванного потенциала?', 'How does spontaneous EEG differ from an evoked potential?', 'Спонтанды ЭЭГ шақырылған потенциалдан қалай ерекшеленеді?'),
task: t('По заданию СРОП №1 составьте таблицу: метод, измеряемый сигнал, временное разрешение, возможный артефакт и ограничение вывода. Сравните ЭЭГ, вызванные потенциалы и структурную визуализацию. Реоэнцефалографию обсудите отдельно: она не является прямым измерением мозгового кровотока.', 'Adapt the workbook task into a table: method, measured signal, temporal resolution, possible artifact and limit of inference. Compare EEG, evoked potentials and structural imaging. Discuss rheoencephalography separately: it does not directly measure cerebral blood flow.', 'СРОП №1 тапсырмасы бойынша әдіс, өлшенетін сигнал, уақыттық ажыратымдылық, ықтимал артефакт және қорытынды шектеуі бар кесте құрыңыз. ЭЭГ, шақырылған потенциалдар мен құрылымдық бейнелеуді салыстырыңыз. Реоэнцефалография ми қан ағымын тікелей өлшемейді.'),
terms: [t('Электроэнцефалография', 'Electroencephalography', 'Электроэнцефалография'), t('Артефакт регистрации', 'Recording artifact', 'Тіркеу артефактісі')] },
{ id: 3, sources: ['cells'], materials: [],
mechanism: t('Дендриты и тело нейрона получают входы, начальный сегмент аксона часто запускает потенциал действия, аксон проводит его, а окончания передают сигнал клеткам-мишеням. Эта схема полезна для большинства изучаемых нейронов, но не охватывает всё разнообразие их строения.', 'Dendrites and soma receive inputs, the axon initial segment often initiates an action potential, the axon conducts it, and terminals signal to target cells. This scheme helps with many neurons but does not describe every neuronal morphology.', 'Дендриттер мен нейрон денесі кіріс сигналдарын қабылдайды, аксонның бастапқы сегменті жиі әрекет потенциалын бастайды, аксон оны өткізеді, ал ұштары нысана жасушаларға сигнал береді. Бұл схема нейрондардың барлық түрін қамтымайды.'),
interpretation: t('Астроциты участвуют в поддержании внеклеточной среды и работе синапсов. Олигодендроциты образуют миелин в ЦНС, шванновские клетки — в ПНС, микроглия участвует в иммунных процессах. Изменение среды вокруг нейрона может нарушать сигнализацию без разрыва аксона.', 'Astrocytes help regulate the extracellular environment and synapses. Oligodendrocytes form CNS myelin, Schwann cells form PNS myelin, and microglia participate in immune processes. Changes around a neuron may disrupt signaling without severing its axon.', 'Астроциттер жасушадан тыс ортаны және синапстар қызметін реттеуге қатысады. Олигодендроциттер ОЖЖ-де, Шванн жасушалары ШЖЖ-де миелин түзеді. Микроглия иммундық үдерістерге қатысады. Ортаның өзгеруі аксон үзілмесе де сигнал беруді бұзуы мүмкін.'),
question: t('Почему глия важна для электрической сигнализации нейрона?', 'Why is glia important for neuronal electrical signaling?', 'Глия нейронның электрлік сигнал беруі үшін неге маңызды?'),
task: t('На схеме нейрона подпишите вход, область запуска импульса, проводящий участок и выход. Предскажите, какие процессы изменятся при утрате миелина и при нарушении поддержания внеклеточного K⁺; объясните различие.', 'Label input, impulse initiation, conduction and output on a neuron diagram. Predict which processes change with loss of myelin versus impaired extracellular K⁺ regulation; explain the difference.', 'Нейрон сызбасында кіріс, импульс басталатын аймақ, өткізетін бөлік пен шығысты белгілеңіз. Миелин жоғалғанда және жасушадан тыс K⁺ реттелуі бұзылғанда қандай үдерістер өзгеретінін болжап, айырмасын түсіндіріңіз.'), terms: [t('Нейрон', 'Neuron', 'Нейрон'), t('Миелин', 'Myelin', 'Миелин')] },
{ id: 4, sources: ['potential'], materials: [],
mechanism: t('Потенциал покоя определяется ионными градиентами и относительной проницаемостью мембраны. В покое вклад K⁺ обычно велик. При достижении порога быстро активируются потенциал-зависимые Na⁺-каналы: вход Na⁺ формирует восходящую фазу потенциала действия. Затем Na⁺-каналы инактивируются, а открытие K⁺-каналов усиливает выход K⁺ и реполяризацию; сохраняющаяся K⁺-проводимость может вызвать следовую гиперполяризацию. Na⁺/K⁺-АТФаза поддерживает градиенты во времени, но не является причиной быстрой реполяризации каждого отдельного импульса.', 'Resting potential depends on ionic gradients and relative membrane permeability, with a large K⁺ contribution in many neurons. At threshold, voltage-gated Na⁺ channels rapidly activate and Na⁺ influx produces the action-potential upstroke. Na⁺ channels then inactivate while K⁺ conductance rises, promoting K⁺ efflux and repolarization; persistent K⁺ conductance may produce an after-hyperpolarization. The Na⁺/K⁺ ATPase maintains gradients over time but does not directly cause the rapid repolarization of each spike.', 'Тыныштық потенциалы иондық градиенттер мен мембрананың салыстырмалы өткізгіштігіне тәуелді, көптеген нейрондарда K⁺ үлесі жоғары. Табалдырыққа жеткенде кернеуге тәуелді Na⁺ арналары тез ашылып, Na⁺ кіруі әрекет потенциалының көтерілу фазасын туғызады. Кейін Na⁺ арналары инактивацияланып, K⁺ өткізгіштігі артады да K⁺ шығуы реполяризацияны қамтамасыз етеді; K⁺ өткізгіштігінің сақталуы кейінгі гиперполяризация туғызуы мүмкін. Na⁺/K⁺-АТФаза градиенттерді ұзақ уақытта сақтайды, бірақ әр импульстің жылдам реполяризациясын тікелей жасамайды.'),
interpretation: t('Движущая сила зависит от разности мембранного и равновесного потенциалов. Повышение внеклеточного K⁺ обычно деполяризует мембрану, однако длительная деполяризация может инактивировать Na⁺-каналы и снизить способность генерировать импульсы. Абсолютный рефрактерный период в основном связан с инактивацией Na⁺-каналов; относительный — с неполным восстановлением Na⁺-каналов и сохраняющейся K⁺-проводимостью. Сила надпорогового стимула кодируется прежде всего частотой импульсов, а не увеличением амплитуды отдельного потенциала действия.', 'Driving force depends on the difference between membrane and equilibrium potentials. Raising extracellular K⁺ usually depolarizes the membrane, yet sustained depolarization can inactivate Na⁺ channels and reduce spike generation. The absolute refractory period mainly reflects Na⁺-channel inactivation; the relative period reflects incomplete Na⁺-channel recovery plus persistent K⁺ conductance. Suprathreshold stimulus strength is encoded mainly by firing frequency rather than by increasing the amplitude of an individual action potential.', 'Қозғаушы күш мембраналық және тепе-теңдік потенциалдарының айырмасына тәуелді. Жасушадан тыс K⁺ артуы мембрананы әдетте деполяризациялайды, бірақ ұзақ деполяризация Na⁺ арналарын инактивациялап, импульс түзу қабілетін төмендетуі мүмкін. Абсолютті рефрактерлік кезең негізінен Na⁺ арналарының инактивациясымен, салыстырмалы кезең олардың толық қалпына келмеуі және сақталған K⁺ өткізгіштігімен байланысты. Табалдырықтан жоғары стимул күші жеке әрекет потенциалы амплитудасымен емес, көбіне импульс жиілігімен кодталады.'),
question: t('Как последовательное изменение Na⁺- и K⁺-проводимости формирует фазы потенциала действия и рефрактерность?', 'How do sequential changes in Na⁺ and K⁺ conductance generate action-potential phases and refractoriness?', 'Na⁺ және K⁺ өткізгіштігінің кезекті өзгеруі әрекет потенциалы фазалары мен рефрактерлікті қалай қалыптастырады?'),
task: t('Сначала измените внеклеточный K⁺ в интерактивной модели и запишите Vm в таблицу. Затем на схеме потенциала действия отметьте порог, деполяризацию, реполяризацию, следовую гиперполяризацию, абсолютный и относительный рефрактерные периоды. Для каждой фазы укажите состояние Na⁺- и K⁺-каналов и объясните, почему Na⁺/K⁺-насос нельзя считать механизмом быстрой реполяризации.', 'First change extracellular K⁺ in the interactive model and record Vm in the table. Then label threshold, depolarization, repolarization, after-hyperpolarization, and absolute and relative refractory periods on an action-potential trace. For each phase, state the Na⁺- and K⁺-channel state and explain why the Na⁺/K⁺ pump is not the mechanism of rapid repolarization.', 'Алдымен интерактивті модельде жасушадан тыс K⁺ мөлшерін өзгертіп, Vm нәтижесін кестеге жазыңыз. Содан кейін әрекет потенциалы сызбасында табалдырықты, деполяризацияны, реполяризацияны, кейінгі гиперполяризацияны, абсолютті және салыстырмалы рефрактерлік кезеңдерді белгілеңіз. Әр фазада Na⁺ және K⁺ арналарының күйін көрсетіп, Na⁺/K⁺ сорғысы жылдам реполяризация механизмі емес екенін түсіндіріңіз.'),
terms: [t('Потенциал действия', 'Action potential', 'Әрекет потенциалы'), t('Рефрактерный период', 'Refractory period', 'Рефрактерлік кезең')] },
{ id: 5, sources: ['synapse'], materials: [],
mechanism: t('В химическом синапсе приход импульса открывает пресинаптические Ca²⁺-каналы. Вход Ca²⁺ способствует слиянию везикул и выделению медиатора, который действует на постсинаптические рецепторы. Ионотропные рецепторы непосредственно меняют проводимость, метаботропные действуют через внутриклеточные пути.', 'At a chemical synapse, an impulse opens presynaptic Ca²⁺ channels. Ca²⁺ entry promotes vesicle fusion and transmitter release onto postsynaptic receptors. Ionotropic receptors directly change conductance; metabotropic receptors act through intracellular pathways.', 'Химиялық синапста импульс пресинапстық Ca²⁺ арналарын ашады. Ca²⁺ енуі везикулалардың қосылуы мен медиатор бөлінуіне ықпал етеді. Ионотроптық рецепторлар өткізгіштікті тікелей, метаботроптық рецепторлар жасушаішілік жолдар арқылы өзгертеді.'),
interpretation: t('Один медиатор может давать разные эффекты на разных рецепторах. Возбуждение или торможение нельзя установить только по его названию. Ответ зависит также от ионных градиентов, места контакта и исходного состояния клетки. Нейромодуляция меняет свойства и режим работы сети.', 'The same transmitter can have different effects at different receptors. Its name alone does not establish excitation or inhibition. Ion gradients, synapse location and cell state also matter. Neuromodulation changes network properties and operating modes.', 'Бір медиатор әртүрлі рецепторларда түрлі әсер бере алады. Оның атауы ғана қозуды не тежелуді анықтамайды. Иондық градиенттер, түйісу орны және жасушаның бастапқы күйі де маңызды. Нейромодуляция желінің қасиеттерін өзгертеді.'),
question: t('Почему действие медиатора зависит от рецептора?', 'Why does a transmitter’s effect depend on its receptor?', 'Медиатор әсері рецепторға неге тәуелді?'),
task: t('Сравните блокаду пресинаптического входа Ca²⁺ и блокаду постсинаптических рецепторов. Для каждой укажите, достиг ли импульс окончания, выделился ли медиатор и возник ли вызванный ответ в упрощённой модели.', 'Compare blocked presynaptic Ca²⁺ entry with blocked postsynaptic receptors. State whether an impulse arrives, transmitter is released and an evoked response occurs in each simplified model.', 'Пресинапстық Ca²⁺ енуінің және постсинапстық рецепторлардың бөгелуін салыстырыңыз. Әр модельде импульс жеткенін, медиатор бөлінгенін және шақырылған жауап туғанын көрсетіңіз.'), terms: [t('Ионотропный рецептор', 'Ionotropic receptor', 'Ионотроптық рецептор'), t('Нейромодуляция', 'Neuromodulation', 'Нейромодуляция')] },
{ id: 6, sources: ['synapse'], materials: ['ПЗ 7: связь с торможением поведения'],
mechanism: t('Возбуждающие входы увеличивают вероятность разряда нейрона, тормозные уменьшают её в рассматриваемых условиях. Эффект зависит от изменения проводимости и движущей силы для ионов. Торможение может действовать шунтированием и не всегда требует заметной гиперполяризации.', 'Excitatory inputs increase firing probability; inhibitory inputs decrease it under the conditions considered. Effects depend on conductance and ionic driving forces. Inhibition can act by shunting and need not produce marked hyperpolarization.', 'Қоздырушы кірістер нейрон разрядының ықтималдығын арттырады, тежеуші кірістер оны азайтады. Әсер өткізгіштік пен иондардың қозғаушы күшіне тәуелді. Шунттаушы тежелу айқын гиперполяризациясыз да болуы мүмкін.'),
interpretation: t('Пространственная суммация объединяет разные входы, временная — близкие по времени события. Итог определяет напряжение в области запуска импульса. Торможение поведения при угасании условной реакции и тормозный синапс — разные уровни описания; их нельзя автоматически отождествлять.', 'Spatial summation combines different inputs; temporal summation combines closely timed events. The net effect influences voltage at the trigger region. Behavioral extinction and an inhibitory synapse are different explanatory levels and must not be equated automatically.', 'Кеңістіктік суммация әртүрлі кірістерді, уақыттық суммация жақын мезеттегі оқиғаларды біріктіреді. Нәтиже импульс басталатын аймақтағы кернеуге әсер етеді. Мінез-құлықтағы сөну мен тежеуші синапс — түсіндірудің әртүрлі деңгейлері.'),
question: t('Может ли торможение быть эффективным без сильной гиперполяризации?', 'Can inhibition be effective without strong hyperpolarization?', 'Күшті гиперполяризациясыз тежелу тиімді болуы мүмкін бе?'),
task: t('Сравните одинаковые возбуждающие входы, пришедшие одновременно и далеко друг от друга во времени. Затем добавьте тормозную проводимость. Объясните, какие данные нужны для прогноза разряда вместо простого подсчёта плюсов и минусов.', 'Compare equal excitatory inputs arriving together or far apart in time. Then add inhibitory conductance. Explain which measurements are needed to predict firing instead of merely counting positive and negative inputs.', 'Бір мезетте және уақыт жағынан алшақ келген бірдей қоздырушы кірістерді салыстырыңыз. Тежеуші өткізгіштікті қосыңыз. Разрядты болжау үшін қандай деректер қажет екенін түсіндіріңіз.'), terms: [t('Суммация', 'Summation', 'Суммация'), t('Шунтирующее торможение', 'Shunting inhibition', 'Шунттаушы тежелу')] },
{ id: 7, sources: ['motor'], materials: ['Силлабус: спинальные рефлексы', 'ПЗ 7: условные и безусловные реакции'],
mechanism: t('Рефлекторная реакция связывает рецептор, афферентное проведение, центральную обработку, эфферентный выход и эффектор. В рефлексе растяжения мышечное веретено сообщает об изменении длины мышцы. Моносинаптическое возбуждение мотонейронов дополняется работой интернейронов и другими входами.', 'A reflex links receptors, afferent conduction, central processing, efferent output and effectors. In a stretch reflex, muscle spindles signal changes in muscle length. Monosynaptic motor-neuron excitation is accompanied by interneuronal circuits and other inputs.', 'Рефлекс рецепторды, афференттік өткізуді, орталық өңдеуді, эфференттік шығысты және эффекторды байланыстырады. Созылу рефлексінде бұлшықет ұршығы ұзындық өзгерісін хабарлайды. Моносинапстық қозумен қатар интернейрондық тізбектер жұмыс істейді.'),
interpretation: t('Рефлекс изменяется под влиянием нисходящих команд и состояния сети. Отсутствие движения может быть связано с любым звеном дуги и само по себе не локализует нарушение. Согласованное движение использует как возбуждение нужных мышц, так и ограничение активности антагонистов.', 'Reflexes vary with descending commands and network state. Absent movement may reflect any part of the arc and does not localize a lesion by itself. Coordinated movement requires both recruitment of needed muscles and reduced antagonist activity.', 'Рефлекс төмендейтін командалар мен желі күйіне байланысты өзгереді. Қозғалыстың болмауы доғаның кез келген буынымен байланысты болуы мүмкін және бұзылысты жалғыз өзі анықтамайды. Үйлесімді қозғалыс қажетті бұлшықеттерді қоздырумен қатар антагонистер белсенділігін шектейді.'),
question: t('Почему слабый рефлекс нельзя объяснить только состоянием мышцы?', 'Why can a weak reflex not be explained by muscle state alone?', 'Әлсіз рефлексті тек бұлшықет күйімен неге түсіндіруге болмайды?'),
task: t('По теме силлабуса нарисуйте дугу рефлекса растяжения и путь реципрокного торможения. Рассмотрите три причины отсутствия ответа: нарушен вход, нарушен выход, изменено состояние сети. Для каждой предложите дополнительное наблюдение.', 'Using the syllabus topic, draw the stretch-reflex arc and reciprocal inhibition. Consider absent input, absent output and altered network state as explanations for no response. Propose an additional observation for each.', 'Силлабус тақырыбы бойынша созылу рефлексі мен реципроктық тежелуді сызыңыз. Жауап болмауының үш себебін қарастырыңыз: кіріс, шығыс және желі күйінің өзгеруі. Әрқайсысына қосымша бақылау ұсыныңыз.'), terms: [t('Рефлекторная дуга', 'Reflex arc', 'Рефлекторлық доға'), t('Реципрокное торможение', 'Reciprocal inhibition', 'Реципроктық тежелу')] },
{ id: 8, sources: ['cns'], materials: ['Силлабус: таблица проводящих путей', 'СРОП 2–4: схемы сенсорных систем'],
mechanism: t('Восходящие пути передают сенсорную информацию, нисходящие участвуют в управлении движением и другими функциями. Для каждого пути прослеживают происхождение, переключения, перекрёст и конечную мишень. Сторона нарушения зависит от того, где оно находится относительно перекрёста.', 'Ascending pathways carry sensory information; descending pathways contribute to movement and other functions. Trace each pathway’s origin, relays, crossing and target. The affected side depends on the site relative to the crossing.', 'Жоғарылайтын жолдар сенсорлық ақпарат береді, төмендейтін жолдар қозғалыс пен басқа қызметтерді басқарады. Әр жолдың басталуын, ауысуын, айқасуын және нысанасын қадағалайды. Бұзылыс жағы айқасқа қатысты орналасуына тәуелді.'),
interpretation: t('Задние столбы и медиальная петля передают тонкое осязание и сознательную проприоцепцию; антеролатеральная система участвует в передаче боли и температуры. Их перекрёсты находятся на разных уровнях. Общая фраза «чувствительность нарушена» недостаточна для сравнения этих путей.', 'Dorsal columns and the medial lemniscus carry discriminative touch and conscious proprioception; the anterolateral system contributes to pain and temperature signaling. They cross at different levels. “Sensation is impaired” is too vague to compare the pathways.', 'Артқы бағандар мен медиалдық ілмек нәзік сипап сезу мен саналы проприоцепцияны өткізеді; антеролатералдық жүйе ауырсыну мен температураға қатысады. Олардың айқасу деңгейлері әртүрлі. «Сезімталдық бұзылған» деген жалпылама мәлімет жеткіліксіз.'),
question: t('Зачем при анализе пути указывать уровень перекрёста?', 'Why specify the level where a pathway crosses?', 'Жолды талдағанда айқасу деңгейін неге көрсету керек?'),
task: t('Адаптируйте таблицу силлабуса: модальность, первый нейрон, центральное переключение, перекрёст, мишень. Заполните строки для задних столбов и антеролатерального пути. Предскажите сторону сенсорного изменения до и после перекрёста.', 'Adapt the syllabus table: modality, first neuron, central relay, crossing and target. Complete rows for dorsal columns and the anterolateral pathway. Predict the affected side before and after the crossing.', 'Силлабус кестесін бейімдеңіз: модальдық, бірінші нейрон, орталық ауысу, айқасу, нысана. Артқы бағандар мен антеролатералдық жолды салыстырып, айқасқа дейінгі және кейінгі өзгеріс жағын болжаңыз.'), terms: [t('Афферентный путь', 'Afferent pathway', 'Афференттік жол'), t('Перекрёст', 'Decussation', 'Айқасу')] },
{ id: 9, sources: ['cns','motor'], materials: ['Силлабус: спинной мозг и спинальные рефлексы'],
mechanism: t('Спинной мозг содержит сегментарные сети и проводящие пути. Чувствительные волокна входят преимущественно через задние корешки; аксоны соматических мотонейронов выходят через передние. Интернейроны объединяют сенсорные и нисходящие входы, согласуя выход к мышцам.', 'The spinal cord contains segmental circuits and long pathways. Sensory fibers mainly enter through dorsal roots; somatic motor-neuron axons leave through ventral roots. Interneurons combine sensory and descending inputs to coordinate muscle output.', 'Жұлында сегменттік желілер мен өткізгіш жолдар бар. Сезімтал талшықтар көбіне артқы түбіршектермен кіреді, соматикалық мотонейрон аксондары алдыңғы түбіршектермен шығады. Интернейрондар сенсорлық және төмендейтін кірістерді біріктіреді.'),
interpretation: t('Перерыв связи с головным мозгом не равен уничтожению всех сегментарных цепей. Однако сразу после тяжёлого поражения рефлексы могут угнетаться при спинальном шоке, а позже изменяться иначе. Для объяснения необходимы уровень поражения, время после него и исследуемая функция.', 'Disconnecting the brain does not destroy every segmental circuit. Reflexes may nevertheless be depressed during acute spinal shock and change later. Explanation requires lesion level, time since injury and the function tested.', 'Мимен байланыстың үзілуі барлық сегменттік тізбектің жойылуын білдірмейді. Бірақ ауыр зақымнан кейін жұлындық шок кезінде рефлекстер бәсеңдеп, кейін өзгеше өзгеруі мүмкін. Түсіндіру үшін деңгей, уақыт және зерттелген қызмет қажет.'),
question: t('Чем повреждение корешка отличается от нарушения нисходящего пути?', 'How does root damage differ from disruption of a descending pathway?', 'Түбіршек зақымы төмендейтін жол бұзылысынан қалай ерекшеленеді?'),
task: t('Разметьте задний корешок, задний рог, передний рог и передний корешок. Для каждого обозначьте преимущественную функцию. По теме занятия объясните, почему исследование одного сухожильного рефлекса не описывает всю работу спинного мозга.', 'Label dorsal root, dorsal horn, ventral horn and ventral root with their main functions. Explain why one tendon reflex does not describe all spinal-cord function.', 'Артқы түбіршек, артқы мүйіз, алдыңғы мүйіз және алдыңғы түбіршекті белгілеп, негізгі қызметтерін жазыңыз. Бір сіңір рефлексі жұлынның барлық қызметін неге сипаттамайды?'), terms: [t('Сегментарная сеть', 'Segmental circuit', 'Сегменттік желі'), t('Спинальный шок', 'Spinal shock', 'Жұлындық шок')] },
{ id: 10, sources: ['cns'], materials: ['Силлабус: стволовые структуры и тонические рефлексы'],
mechanism: t('Продолговатый мозг, мост и средний мозг объединяют проводящие пути, ядра черепных нервов и распределённые регуляторные сети. Ствол участвует в дыхательной и сердечно-сосудистой регуляции, ориентировочных реакциях, позе и движениях глаз. Эти функции взаимодействуют с другими отделами ЦНС.', 'Medulla, pons and midbrain contain long pathways, cranial-nerve nuclei and distributed regulatory networks. The brainstem contributes to respiratory and cardiovascular regulation, orienting, posture and eye movements in interaction with other CNS regions.', 'Сопақша ми, көпір және ортаңғы ми өткізгіш жолдарды, бассүйек жүйке ядроларын және реттеуші желілерді біріктіреді. Ми сабауы тыныс, жүрек-қантамыр реттелуіне, бағдарлау реакцияларына, дене қалпы мен көз қозғалысына қатысады.'),
interpretation: t('Ретикулярная формация — система взаимосвязанных групп нейронов, а не один центр. Её восходящие связи участвуют в поддержании бодрствования; нисходящие влияют на позный и двигательный контроль. Изменение сознания само по себе не указывает на единственную структуру.', 'The reticular formation is a system of interconnected neuronal groups rather than one center. Ascending connections help maintain arousal; descending connections influence posture and movement. Altered consciousness alone does not identify one structure.', 'Ретикулярлық формация — бір орталық емес, өзара байланысқан нейрон топтарының жүйесі. Жоғарылайтын байланыстар сергектікті, төмендейтін байланыстар дене қалпы мен қозғалысты реттеуге қатысады. Сана өзгерісі бір құрылымды ғана көрсетпейді.'),
question: t('Почему ствол мозга нельзя считать только проводником?', 'Why is the brainstem more than a conduit?', 'Ми сабауын тек өткізгіш деп неге қарастыруға болмайды?'),
task: t('По разделу силлабуса составьте схему: сенсорный вход → стволовые сети → движения глаз, позная реакция и изменение бодрствования. Для каждого выхода укажите связь с другим отделом ЦНС. Не сводите все реакции к одному ядру.', 'Build a syllabus-linked scheme: sensory input → brainstem networks → eye movement, postural response and arousal change. For each output name a connection with another CNS region; do not reduce every response to one nucleus.', 'Сенсорлық кіріс → ми сабауы желілері → көз қозғалысы, позалық жауап және сергектік өзгерісі сызбасын құрыңыз. Әр шығыстың ОЖЖ-нің басқа бөлімімен байланысын көрсетіңіз.'), terms: [t('Ретикулярная формация', 'Reticular formation', 'Ретикулярлық формация'), t('Бодрствование', 'Wakefulness', 'Сергектік')] },
{ id: 11, sources: ['motor'], materials: ['Силлабус: тонические рефлексы', 'ПЗ 5: вестибулярные функции'],
mechanism: t('Двигательное управление объединяет цель, выбор действия, подготовку команды и её выполнение. Кора, базальные ганглии, мозжечок, ствол и спинной мозг выполняют разные, взаимодействующие задачи. Конечный нервный выход к скелетной мышце осуществляется через мотонейрон и нервно-мышечный синапс.', 'Motor control integrates goals, action selection, command preparation and execution. Cortex, basal ganglia, cerebellum, brainstem and spinal cord have interacting roles. The final neural output to skeletal muscle passes through a motor neuron and neuromuscular junction.', 'Қимыл басқаруы мақсатты, әрекет таңдауды, команданы дайындауды және орындауды біріктіреді. Қыртыс, базальды ганглийлер, мишық, ми сабауы мен жұлын өзара әрекеттеседі. Қаңқа бұлшықетіне соңғы жүйкелік шығыс мотонейрон және жүйке-бұлшықет синапсы арқылы өтеді.'),
interpretation: t('Предварительное управление использует ожидаемые условия, обратная связь сообщает о результате. Изменение поверхности опоры требует коррекции позы и движения по сенсорным данным. Точность движения нельзя оценивать только по максимальной силе мышцы.', 'Feedforward control uses expected conditions; feedback reports the result. A change in the support surface requires sensory-guided adjustment of posture and movement. Movement accuracy cannot be assessed by maximum muscle strength alone.', 'Алдын ала басқару күтілетін жағдайларды пайдаланады, кері байланыс нәтиже туралы хабарлайды. Тірек беті өзгергенде сенсорлық деректерге сай дене қалпы мен қозғалыс түзетіледі. Қозғалыс дәлдігі тек бұлшықеттің ең жоғары күшімен бағаланбайды.'),
question: t('Чем предварительная команда отличается от коррекции по обратной связи?', 'How does a feedforward command differ from feedback correction?', 'Алдын ала команда кері байланыс арқылы түзетуден қалай ерекшеленеді?'),
task: t('Разберите шаг по неровной поверхности: цель, план, сенсорный вход, двигательный выход, результат. По материалам вестибулярного занятия объясните, почему зрительные и проприоцептивные сигналы могут частично компенсировать изменение одного входа.', 'Analyze a step on uneven ground: goal, plan, sensory input, motor output and result. Using the vestibular lesson, explain how visual and proprioceptive inputs may partly compensate for changes in one input.', 'Тегіс емес беттегі қадамды талдаңыз: мақсат, жоспар, сенсорлық кіріс, қозғалтқыш шығыс, нәтиже. Көру және проприоцепциялық сигналдардың бір кіріс өзгерісін ішінара қалай өтейтінін түсіндіріңіз.'), terms: [t('Предварительное управление', 'Feedforward control', 'Алдын ала басқару'), t('Двигательная обратная связь', 'Motor feedback', 'Қимылдық кері байланыс')] },
{ id: 13, sources: ['motor'], materials: ['Силлабус: мозжечковые пробы', 'ПЗ 5: равновесие'],
mechanism: t('Мозжечок получает информацию о движении, проприоцептивные и другие сенсорные сигналы. Через связи со стволом и таламокортикальными сетями он участвует в настройке времени, точности и согласованности движения. Его работа важна для двигательного обучения и коррекции ошибок.', 'The cerebellum receives movement-related information, proprioception and other sensory inputs. Through brainstem and thalamocortical connections it contributes to timing, accuracy and coordination. It is important for motor learning and error correction.', 'Мишық қозғалыс туралы ақпаратты, проприоцепциялық және басқа сенсорлық сигналдарды қабылдайды. Ми сабауы және таламо-қыртыстық желілер арқылы қозғалыстың уақытын, дәлдігін және үйлесімін реттеуге, қателерді түзетуге қатысады.'),
interpretation: t('Дисметрия и нарушение последовательности быстрых движений описывают особенности координации, а не просто недостаток силы. Устойчивость тела зависит также от зрения, вестибулярной системы и проприоцепции. Отдельная проба не устанавливает причину нарушения равновесия.', 'Dysmetria and impaired rapid alternating movements describe coordination rather than just weakness. Balance also depends on vision, vestibular input and proprioception. A single test does not establish the cause of imbalance.', 'Дисметрия мен жылдам кезектесетін қимылдың бұзылуы жай әлсіздікті емес, үйлесімділік ерекшелігін сипаттайды. Тепе-теңдік көруге, вестибулярлық жүйеге және проприоцепцияға да тәуелді. Бір сынама бұзылыс себебін анықтамайды.'),
question: t('Почему сохранённая сила не гарантирует точность движения?', 'Why does preserved strength not guarantee movement accuracy?', 'Күштің сақталуы қозғалыс дәлдігіне неге кепіл болмайды?'),
task: t('По заданию силлабуса сравните точность достижения цели и способность развить силу. Опишите, какие ошибки оценивают при пальце-носовой пробе и быстрых чередующихся движениях. Объясните, какие другие системы следует учитывать при неустойчивости.', 'Compare target-reaching accuracy with force production. Describe errors assessed in finger-to-nose and rapid alternating movement tasks. Explain which other systems matter when balance is impaired.', 'Нысанаға жету дәлдігі мен күш өндіруді салыстырыңыз. Саусақ-мұрын және жылдам кезектесетін қимыл сынамаларында қандай қателер бағаланатынын жазыңыз. Тұрақсыздықта басқа қандай жүйелер ескеріледі?'), terms: [t('Дисметрия', 'Dysmetria', 'Дисметрия'), t('Двигательное обучение', 'Motor learning', 'Қимылға үйрену')] },
{ id: 14, sources: ['cns'], materials: ['Силлабус: ядра и функции таламуса', 'СРОП 2–4: сенсорные пути'],
mechanism: t('Таламус состоит из нескольких групп ядер со специализированными связями. Сенсорные ядра передают и преобразуют информацию для коры; другие ядра участвуют в двигательных и ассоциативных контурах. Обратные корково-таламические связи делают эту систему взаимодействующей, а не односторонней.', 'The thalamus contains nuclear groups with specialized connections. Sensory nuclei relay and transform information for cortex; other nuclei participate in motor and associative loops. Corticothalamic feedback makes this an interacting system rather than a one-way relay.', 'Таламус маманданған байланыстары бар ядро топтарынан тұрады. Сенсорлық ядролар ақпаратты қыртысқа беріп, өңдейді; басқа ядролар қозғалтқыш және ассоциациялық контурларға қатысады. Қыртыс-таламус кері байланысы жүйені екіжақты етеді.'),
interpretation: t('Зрительная информация связана с латеральным коленчатым телом, слуховая — с медиальным. Соматосенсорные входы переключаются в вентральных задних ядрах. Первичный обонятельный путь достигает обонятельной коры без обязательного предварительного таламического переключения; дальнейшая обработка включает более широкие сети.', 'Visual information involves the lateral geniculate body and auditory information the medial geniculate body. Somatosensory inputs relay in ventral posterior nuclei. The primary olfactory pathway reaches olfactory cortex without an obligatory earlier thalamic relay; later processing involves wider networks.', 'Көру ақпараты латералдық, есту ақпараты медиалдық тізелі денемен байланысты. Соматосенсорлық кірістер вентралдық артқы ядроларда ауысады. Алғашқы иіс сезу жолы иіс қыртысына міндетті алдын ала таламустық ауысусыз жетеді.'),
question: t('Все ли сенсорные сигналы обязательно проходят таламус до первого коркового входа?', 'Must all sensory signals pass through thalamus before their first cortical input?', 'Барлық сенсорлық сигналдар алғашқы қыртыстық кіріске дейін таламустан міндетті түрде өте ме?'),
task: t('Заполните таблицу из силлабуса: ядро, основной вход, корковая мишень, функция. Сравните зрение, слух и соматосенсорную систему. Отдельно отметьте особенности обонятельного пути и обратных связей.', 'Complete the syllabus table: nucleus, major input, cortical target and function. Compare vision, hearing and somatosensation; note olfactory exceptions and feedback connections separately.', 'Силлабус кестесін толтырыңыз: ядро, негізгі кіріс, қыртыстық нысана, қызмет. Көру, есту және соматосенсорлық жүйені салыстырыңыз. Иіс жолының ерекшелігі мен кері байланыстарды бөлек көрсетіңіз.'), terms: [t('Таламическое ядро', 'Thalamic nucleus', 'Таламус ядросы'), t('Таламокортикальная петля', 'Thalamocortical loop', 'Таламо-қыртыстық контур')] },
{ id: 15, sources: ['cns','sleep'], materials: ['Силлабус: ядра гипоталамуса', 'СРО 5', 'СРО 6'],
mechanism: t('Гипоталамус объединяет сведения о внутренней среде с сигналами других отделов мозга. Через вегетативные, эндокринные и поведенческие выходы он участвует в регуляции температуры, водного баланса, питания и суточных ритмов. Разные группы нейронов образуют взаимодействующие контуры.', 'The hypothalamus integrates internal-state information with other brain inputs. Autonomic, endocrine and behavioral outputs contribute to temperature, water balance, feeding and circadian regulation. Different neuronal groups form interacting control circuits.', 'Гипоталамус ішкі орта туралы деректерді мидың басқа бөлімдерінен келген сигналдармен біріктіреді. Вегетативтік, эндокриндік және мінез-құлық шығыстары арқылы температураны, су теңгерімін, қоректенуді және тәуліктік ырғақтарды реттеуге қатысады.'),
interpretation: t('При изменении осмолярности или объёма жидкости включаются разные рецепторные и регуляторные механизмы. Жажда меняет поведение, вазопрессин влияет на удержание воды почками. Эти выходы дополняют друг друга; один гормон не описывает всю систему гомеостаза.', 'Changes in osmolality or fluid volume recruit different sensing and control mechanisms. Thirst changes behavior; vasopressin affects renal water retention. These outputs complement each other, and one hormone does not describe the whole homeostatic system.', 'Осмолярлық немесе сұйықтық көлемі өзгергенде әртүрлі сезу және реттеу тетіктері іске қосылады. Шөлдеу мінез-құлықты, вазопрессин бүйректегі судың сақталуын өзгертеді. Бұл шығыстар бірін-бірі толықтырады.'),
question: t('Зачем одной системе регуляции нужны поведенческий и гормональный выходы?', 'Why does one regulatory system need behavioral and hormonal outputs?', 'Бір реттеу жүйесіне мінез-құлық және гормондық шығыстар неге қажет?'),
task: t('По теме гипоталамуса составьте схему ответа на дефицит воды: наблюдаемая величина, сенсорный вход, интеграция, два выхода и обратная связь. Отличите изменение осмолярности от изменения объёма; не добавляйте назначения препаратов.', 'Map the response to water deficit: monitored variable, sensory input, integration, two outputs and feedback. Distinguish osmolality from volume changes without prescribing drugs.', 'Су тапшылығына жауап сызбасын құрыңыз: бақыланатын шама, сенсорлық кіріс, интеграция, екі шығыс және кері байланыс. Осмолярлық өзгерісін көлем өзгерісінен ажыратыңыз.'), terms: [t('Гомеостаз', 'Homeostasis', 'Гомеостаз'), t('Осморегуляция', 'Osmoregulation', 'Осмореттелу')] },
{ id: 16, sources: ['cns'], materials: ['СРО 2', 'СРО 4', 'Силлабус: лимбическая система'],
mechanism: t('Лимбические сети связывают контекст, память, эмоциональную значимость и мотивацию. Гиппокамп участвует в формировании декларативной памяти и обработке контекста; миндалевидные ядра — в оценке значимости и обучении эмоциональным ассоциациям. Эти структуры взаимодействуют с корой, гипоталамусом и стволом.', 'Limbic networks link context, memory, emotional significance and motivation. The hippocampus contributes to declarative memory formation and context processing; the amygdala contributes to relevance and emotional association learning. These structures interact with cortex, hypothalamus and brainstem.', 'Лимбиялық желілер контексті, жадыны, эмоциялық маңыздылықты және мотивацияны байланыстырады. Гиппокамп декларативтік жады мен контекстке, миндалевидті ядролар маңыздылықты бағалау мен эмоциялық ассоциацияларға қатысады. Олар қыртыспен, гипоталамуспен және ми сабауымен әрекеттеседі.'),
interpretation: t('Эмоция включает субъективное переживание, поведение и вегетативные изменения. Учащение пульса не является однозначным признаком одной эмоции. Функции миндалины не ограничены страхом, а память не хранится целиком в гиппокампе. Объяснение требует учитывать распределённую сеть.', 'Emotion includes subjective experience, behavior and autonomic changes. A faster pulse does not uniquely identify one emotion. Amygdala function is not limited to fear, and memories are not all stored in the hippocampus. Explanation requires distributed networks.', 'Эмоция субъективтік сезімді, мінез-құлықты және вегетативтік өзгерістерді қамтиды. Пульстің жиілеуі бір эмоцияны бірмәнді көрсетпейді. Миндалина қызметі қорқынышпен шектелмейді, ал бүкіл жады гиппокампта ғана сақталмайды.'),
question: t('Почему выражение «один центр эмоций» недостаточно точно?', 'Why is “one emotion center” an inadequate description?', '«Эмоцияның бір орталығы» деген түсінік неге жеткіліксіз?'),
task: t('По СРО 2 сравните функции гиппокампа и миндалевидных ядер. Разберите знакомый сигнал в безопасном и угрожающем контексте: какие сведения меняются, какие выходы возможны и почему пульс не позволяет прочитать содержание переживания?', 'Using ISW 2, compare hippocampal and amygdala functions. Analyze a familiar cue in safe and threatening contexts: what information changes, which outputs may occur and why pulse cannot reveal the content of experience.', 'СРО 2 бойынша гиппокамп пен миндалевидті ядроларды салыстырыңыз. Таныс сигналды қауіпсіз және қауіпті контексте талдаңыз: қандай ақпарат өзгереді, қандай шығыстар болуы мүмкін және пульс сезім мазмұнын неге анықтамайды?'), terms: [t('Гиппокамп', 'Hippocampus', 'Гиппокамп'), t('Эмоциональная значимость', 'Emotional salience', 'Эмоциялық маңыздылық')] },
{ id: 12, sources: ['motor'], materials: ['СРО 1', 'Силлабус: стриопаллидарная система'],
mechanism: t('Базальные ганглии участвуют в выборе и настройке действий через корково-стриато-паллидо-таламические контуры. Полосатое тело получает множество входов; выходные ядра влияют на таламические и стволовые мишени. Это регуляция других двигательных сетей, а не прямой выход к мышце.', 'Basal ganglia contribute to action selection and scaling through cortico-striato-pallido-thalamic circuits. Striatum receives many inputs; output nuclei influence thalamic and brainstem targets. This regulates other motor networks rather than projecting directly to muscle.', 'Базальды ганглийлер қыртыс-стриатум-паллидум-таламус контурлары арқылы әрекет таңдау мен реттеуге қатысады. Стриатум көптеген кірістер алады, шығыс ядролары таламус пен ми сабауына әсер етеді. Олар бұлшықетке тікелей команда бермейді.'),
interpretation: t('Прямой и непрямой пути — полезная начальная схема, но реальные контуры работают параллельно и включают дополнительные связи. Дофамин меняет свойства этих контуров; его действие нельзя описать как одинаковое возбуждение всех нейронов. Замедленное начало движения не тождественно мышечной слабости.', 'Direct and indirect pathways are useful introductory models, but real circuits operate in parallel and contain additional connections. Dopamine modulates these circuits rather than exciting every neuron equally. Slow movement initiation is not the same as muscle weakness.', 'Тікелей және жанама жолдар — бастапқы пайдалы схема, бірақ нақты контурлар қатар жұмыс істеп, қосымша байланыстарды қамтиды. Дофамин барлық нейронды бірдей қоздырмай, контур қасиеттерін өзгертеді. Қимылдың баяу басталуы бұлшықет әлсіздігіне тең емес.'),
question: t('Почему базальные ганглии не заменяют мотонейрон?', 'Why do basal ganglia not replace a motor neuron?', 'Базальды ганглийлер мотонейронды неге алмастырмайды?'),
task: t('По СРО 1 сопоставьте полосатое тело и бледный шар: входы, выходы и роль в контуре. В учебном случае движение начинается медленно, но сила сохранена. Объясните различие между выбором действия и сокращением мышцы без постановки диагноза.', 'Compare striatum and globus pallidus using ISW 1: inputs, outputs and circuit roles. In a teaching example, movement starts slowly despite preserved strength. Explain action selection versus muscle contraction without diagnosing.', 'СРО 1 бойынша стриатум мен бозғылт шардың кірістерін, шығыстарын және контурдағы рөлін салыстырыңыз. Күш сақталғанымен қозғалыс баяу басталатын мысалда әрекет таңдау мен бұлшықет жиырылуын ажыратыңыз.'), terms: [t('Полосатое тело', 'Striatum', 'Стриатум'), t('Бледный шар', 'Globus pallidus', 'Бозғылт шар')] },
{ id: 17, sources: ['cns'], materials: ['СРО 2', 'СРО 4'],
mechanism: t('Миндалина входит в распределённые сети оценки биологической значимости стимулов, эмоционального обучения и памяти. Её ядра получают сенсорную и контекстную информацию и через связи с гипоталамусом, стволом, гиппокампом и корой могут влиять на вегетативные, поведенческие и когнитивные компоненты реакции.', 'The amygdala participates in distributed networks for evaluating biological relevance, emotional learning, and memory. Its nuclei receive sensory and contextual information and can influence autonomic, behavioral, and cognitive components through connections with hypothalamus, brainstem, hippocampus, and cortex.', 'Амигдала тітіркендіргіштердің биологиялық маңызын бағалау, эмоциялық үйрену және жадтың таралған желілеріне қатысады. Оның ядролары сенсорлық және контекстік ақпарат алып, гипоталамус, ми сабауы, гиппокамп және қыртыспен байланыстары арқылы жауаптың вегетативтік, мінез-құлықтық және когнитивтік бөліктеріне әсер етеді.'),
interpretation: t('Функции миндалины не сводятся к «центру страха». Эмоциональная реакция возникает из работы сети и зависит от контекста, опыта и взаимодействия с корой и гиппокампом.', 'Amygdala function is not reducible to a single “fear center.” Emotional responses emerge from network activity and depend on context, experience, and interactions with cortex and hippocampus.', 'Амигдала қызметін тек «қорқыныш орталығы» деп түсіндіруге болмайды. Эмоциялық жауап желілік жұмыстан туындайды және контекстке, тәжірибеге, қыртыс пен гиппокамппен әрекеттесуге тәуелді.'),
question: t('Почему миндалину нельзя считать единственным центром страха?', 'Why should the amygdala not be treated as a single fear center?', 'Неліктен амигдаланы қорқыныштың жалғыз орталығы деп санауға болмайды?'),
task: t('Постройте схему: сенсорный сигнал и контекст → миндалина → гипоталамические/стволовые и корковые выходы. Для каждого звена укажите, какую часть реакции оно помогает объяснить.', 'Build a pathway diagram: sensory signal and context → amygdala → hypothalamic/brainstem and cortical outputs. State which component of the response each connection helps explain.', 'Сызба құрыңыз: сенсорлық сигнал және контекст → амигдала → гипоталамустық/ми бағандық және қыртыстық шығыстар. Әр байланыстың жауаптың қай бөлігін түсіндіретінін көрсетіңіз.'), terms: [t('Миндалина', 'Amygdala', 'Амигдала'), t('Эмоциональное обучение', 'Emotional learning', 'Эмоциялық үйрену')] },
{ id: 18, sources: ['cns'], materials: ['Лекция 1', 'ПЗ 3', 'СРО 4', 'Рабочая тетрадь СРОП №1'],
mechanism: t('Неокортекс обычно имеет шесть слоёв с различными входами, выходами и внутрикорковыми связями. Сенсорные, двигательные и ассоциативные области взаимодействуют. Локализация функции обозначает вклад области в сеть, а не хранение всей сложной функции в одной точке.', 'Neocortex typically has six layers with different inputs, outputs and intracortical connections. Sensory, motor and association areas interact. Functional localization identifies a region’s network contribution rather than placing an entire complex function at one point.', 'Неокортексте әдетте кірістері, шығыстары және ішкі байланыстары әртүрлі алты қабат болады. Сенсорлық, қозғалтқыш және ассоциациялық аймақтар әрекеттеседі. Қызмет локализациясы күрделі қызметтің бір нүктеде сақталуын емес, аймақтың желіге үлесін көрсетеді.'),
interpretation: t('ЭЭГ отражает суммарные электрические процессы и зависит от синхронизации, состояния и способа регистрации. Открывание глаз может уменьшать выраженность заднего альфа-ритма. Скрещивание рук, пальцев или предпочтение руки не являются достаточным исследованием речевой доминантности или личности.', 'EEG reflects summed electrical processes and depends on synchrony, state and recording method. Eye opening can reduce posterior alpha activity. Crossing arms or fingers and handedness alone do not adequately establish language dominance or personality.', 'ЭЭГ жиынтық электр үдерістерін көрсетіп, синхрондалуға, күйге және тіркеу тәсіліне тәуелді. Көз ашылғанда артқы альфа-ырғақ бәсеңдеуі мүмкін. Қолды не саусақты айқастыру және жетекші қол сөйлеу доминанттылығын немесе тұлғаны анықтауға жеткіліксіз.'),
question: t('Чем локализация функции отличается от представления об изолированном центре?', 'How does functional localization differ from an isolated-center model?', 'Қызмет локализациясы оқшауланған орталық ұғымынан қалай ерекшеленеді?'),
task: t('По лекции 1 и ПЗ 3 составьте таблицу корковых связей: ассоциативные, комиссуральные, проекционные. Для сравнения ЭЭГ при закрытых и открытых глазах укажите ожидаемое изменение и возможный артефакт. Не выводите диагноз из одного ритма.', 'Use Lecture 1 and Practical 3 to tabulate association, commissural and projection connections. For EEG with eyes closed versus open, predict a change and identify an artifact. Do not infer a diagnosis from one rhythm.', 'Лекция 1 мен ПЗ 3 бойынша ассоциациялық, комиссуралық және проекциялық байланыстар кестесін жасаңыз. Көз жабық және ашық ЭЭГ-ні салыстырғанда күтілетін өзгеріс пен артефактіні көрсетіңіз. Бір ырғақтан диагноз шығармаңыз.'), terms: [t('Корковая сеть', 'Cortical network', 'Қыртыстық желі'), t('Функциональная асимметрия', 'Functional asymmetry', 'Функциялық асимметрия')] },
{ id: 19, sources: ['sensory'], materials: ['СРОП 4', 'Рабочая тетрадь СРОП №4'], mechanism: t('Соматосенсорная система кодирует прикосновение, давление, вибрацию, проприоцепцию, температуру и ноцицептивные сигналы через специализированные рецепторы и восходящие пути.', 'The somatosensory system encodes touch, pressure, vibration, proprioception, temperature, and nociceptive signals through specialized receptors and ascending pathways.', 'Соматосенсорлық жүйе жанасу, қысым, діріл, проприоцепция, температура және ноцицептивтік сигналдарды арнайы рецепторлар мен жоғарылаушы жолдар арқылы кодтайды.'), interpretation: t('Боль не тождественна ноцицепции: субъективное переживание формируется центральной обработкой и контекстом.', 'Pain is not identical to nociception: subjective experience is shaped by central processing and context.', 'Ауырсыну ноцицепциямен бірдей емес: субъективті сезім орталық өңдеу мен контекстке тәуелді.'), question: t('Чем ноцицепция отличается от боли?', 'How does nociception differ from pain?', 'Ноцицепция ауырсынудан қалай ерекшеленеді?'), task: t('Сопоставьте рецептор, проводящий путь и ощущение для прикосновения, проприоцепции, температуры и ноцицепции.', 'Match receptor, pathway, and sensation for touch, proprioception, temperature, and nociception.', 'Жанасу, проприоцепция, температура және ноцицепция үшін рецепторды, жолды және сезімді сәйкестендіріңіз.'), terms:[t('Рецептивное поле','Receptive field','Рецептивтік өріс'),t('Ноцицепция','Nociception','Ноцицепция')] },
{ id: 20, sources: ['sensory'], materials: ['ПЗ 4', 'СРОП 2', 'Рабочая тетрадь СРОП №2'], mechanism: t('Фоторецепторы сетчатки преобразуют свет; сигналы проходят через сети сетчатки, зрительный нерв, хиазму и таламические релейные структуры к зрительной коре.', 'Retinal photoreceptors transduce light; signals pass through retinal circuits, optic nerve, chiasm, thalamic relay structures, and visual cortex.', 'Торқабық фоторецепторлары жарықты түрлендіреді; сигналдар торқабық желілері, көру жүйкесі, хиазма, таламустық реле және көру қыртысы арқылы өтеді.'), interpretation: t('Поля зрения и зрачковые реакции позволяют проверять разные звенья зрительной системы; один тест не оценивает весь зрительный путь.', 'Visual fields and pupillary responses probe different parts of the visual system; no single test assesses the whole pathway.', 'Көру өрістері мен қарашық реакциялары көру жүйесінің әртүрлі буындарын тексереді; бір тест бүкіл жолды бағаламайды.'), question: t('Почему дефект поля зрения помогает локализовать поражение зрительного пути?', 'Why can a visual-field defect help localize a lesion in the visual pathway?', 'Көру өрісінің ақауы көру жолындағы зақымды неге жергіліктендіруге көмектеседі?'), task: t('Свяжите остроту зрения, периметрию, цветовое зрение, слепое пятно и зрачковый рефлекс с проверяемым физиологическим механизмом.', 'Link visual acuity, perimetry, color vision, blind spot, and pupillary reflex to the physiological mechanism each probes.', 'Көру өткірлігі, периметрия, түсті көру, соқыр дақ және қарашық рефлексін тексерілетін физиологиялық механизммен байланыстырыңыз.'), terms:[t('Фототрансдукция','Phototransduction','Фототрансдукция'),t('Поле зрения','Visual field','Көру өрісі')] },
{ id: 21, sources: ['sensory','taste'], materials: ['ПЗ 5', 'ПЗ 6', 'СРОП 3', 'СРОП 4', 'Рабочая тетрадь СРОП №3–4'], mechanism: t('Слуховая, вестибулярная, вкусовая и обонятельная системы используют разные рецепторные механизмы, но каждая преобразует физический или химический стимул в нервный сигнал и передаёт его в специализированные центральные сети.', 'Auditory, vestibular, gustatory, and olfactory systems use different receptor mechanisms, but each transduces a physical or chemical stimulus into neural signals for specialized central networks.', 'Есту, вестибулярлық, дәм және иіс сезу жүйелері әртүрлі рецепторлық тетіктерді қолданады, бірақ әрқайсысы физикалық не химиялық стимулды жүйкелік сигналға түрлендіреді.'), interpretation: t('Костная и воздушная проводимость исследуют разные маршруты доставки звука; равновесие объединяет вестибулярные, зрительные и проприоцептивные сигналы. Вкус и обоняние нельзя объяснять простой картой отдельных зон.', 'Bone and air conduction probe different routes of sound delivery; balance integrates vestibular, visual, and proprioceptive signals. Taste and smell cannot be reduced to simple maps of isolated zones.', 'Сүйек және ауа өткізгіштігі дыбыстың әртүрлі жеткізілу жолдарын тексереді; тепе-теңдік вестибулярлық, көру және проприоцептивтік сигналдарды біріктіреді.'), question: t('Что общего у специальных сенсорных систем и чем различаются их рецепторные механизмы?', 'What do the special sensory systems share, and how do their receptor mechanisms differ?', 'Арнайы сенсорлық жүйелерге не ортақ және олардың рецепторлық тетіктері қалай ерекшеленеді?'), task: t('Сравните воздушную и костную проводимость, вестибулярную трансдукцию, густометрию и ольфактометрию: стимул, рецептор, сигнал и ограничение метода.', 'Compare air/bone conduction, vestibular transduction, gustometry, and olfactometry by stimulus, receptor, signal, and method limitation.', 'Ауа/сүйек өткізгіштігін, вестибулярлық трансдукцияны, густометрия мен ольфактометрияны стимул, рецептор, сигнал және әдіс шектеуі бойынша салыстырыңыз.'), terms:[t('Механотрансдукция','Mechanotransduction','Механотрансдукция'),t('Хеморецепция','Chemoreception','Хеморецепция')] },
{ id: 22, sources: ['autonomic'], materials: ['Силлабус: нервная регуляция органов', 'Лекция 4: связь с регуляцией сердца', 'Лекция 5: связь с мочевыделением'],
mechanism: t('Вегетативные выходы регулируют гладкие мышцы, сердце и железы. Во многих путях между ЦНС и органом работают преганглионарный и постганглионарный нейроны. Симпатические и парасимпатические влияния различаются организацией, медиаторами и рецепторами мишеней; кишечные сети обладают собственными регуляторными возможностями.', 'Autonomic outputs regulate smooth muscle, heart and glands. Many pathways use preganglionic and postganglionic neurons between CNS and organ. Sympathetic and parasympathetic influences differ in organization, transmitters and target receptors; enteric circuits also have intrinsic regulatory capabilities.', 'Вегетативтік шығыстар бірыңғай салалы бұлшықет, жүрек пен бездерді реттейді. Көптеген жолдарда ОЖЖ мен мүше арасында преганглионарлық және постганглионарлық нейрондар бар. Симпатикалық және парасимпатикалық әсерлер ұйымдасуымен, медиаторларымен және рецепторларымен ерекшеленеді.'),
interpretation: t('Эффект зависит от рецептора органа, а не только от названия отдела. Симпатическая активация не означает сокращение всех гладких мышц, парасимпатическая — торможение всех органов. Вегетативный рефлекс следует описывать от рецептора через центральную интеграцию до результата и обратной связи.', 'Effects depend on target receptors, not just the division’s name. Sympathetic activity does not contract every smooth muscle; parasympathetic activity does not inhibit every organ. Trace autonomic reflexes from sensing through central integration to outcome and feedback.', 'Әсер тек бөлім атауына емес, мүше рецепторына тәуелді. Симпатикалық белсенділік барлық тегіс бұлшықетті жиырмайды, парасимпатикалық әсер барлық мүшені тежемейді. Рефлексті рецептордан орталық интеграция, нәтиже және кері байланысқа дейін сипаттаңыз.'),
question: t('Почему один медиатор может вызывать разные изменения в разных органах?', 'Why may one transmitter produce different effects in different organs?', 'Бір медиатор әртүрлі мүшелерде неге түрлі өзгеріс туғызуы мүмкін?'),
task: t('Выделите нервную часть регуляции сердечного ритма из сердечно-сосудистой темы: рецепторный вход, центральные связи, эфферентный путь и мишень. Сравните её с соматическим выходом к скелетной мышце. Не переносите весь раздел кардиофизиологии в этот модуль.', 'Extract neural heart-rate regulation from the cardiovascular topic: receptor input, central connections, efferent pathway and target. Compare it with somatic skeletal-muscle output, keeping the task focused on neural control.', 'Жүрек-қантамыр тақырыбынан жүрек ырғағының жүйкелік реттелуін бөліңіз: рецепторлық кіріс, орталық байланыстар, эфференттік жол және нысана. Оны қаңқа бұлшықетіне соматикалық шығыспен салыстырыңыз.'), terms: [t('Вегетативный ганглий', 'Autonomic ganglion', 'Вегетативтік ганглий'), t('Орган-мишень', 'Target organ', 'Нысана мүше')] },
{ id: 23, sources: ['cns'], materials: ['Лекция 2', 'ПЗ 7', 'СРО 3', 'СРО 4'],
mechanism: t('Обучение меняет поведение на основании опыта. При классическом обусловливании сигнал приобретает предсказательное значение благодаря связи с последующим событием. Формирование реакции зависит от порядка, интервалов, предсказуемости и контекста, а не только от числа сочетаний.', 'Learning changes behavior through experience. In classical conditioning, a cue gains predictive value through its relationship with a later event. Learning depends on timing, predictability and context, not just the number of pairings.', 'Үйрену тәжірибе негізінде мінез-құлықты өзгертеді. Классикалық шарттануда сигнал кейінгі оқиғамен байланысы арқылы болжаушы мәнге ие болады. Реакция қалыптасуы тек үйлестіру санына емес, ретке, аралыққа, болжамдылық пен контекстке тәуелді.'),
interpretation: t('Повторение сигнала без подкрепления может уменьшать реакцию при угасании, но не обязательно стирает исходное обучение. Новый сильный сигнал может изменять выполнение через ориентировочную реакцию. Типологический опросник и бытовые тесты не являются диагнозом, мерой способностей или жёстким генетическим типом.', 'Repeated unreinforced cues can reduce responding through extinction without necessarily erasing earlier learning. A salient new stimulus may change performance through orienting. Typology questionnaires and informal tests are not diagnoses, ability measures or fixed genetic categories.', 'Сигналды нығайтусыз қайталау реакцияны сөндіруі мүмкін, бірақ бастапқы үйренуді міндетті түрде өшірмейді. Жаңа айқын стимул бағдарлау арқылы орындауды өзгерте алады. Типологиялық сауалнама диагноз, қабілет өлшемі немесе өзгермейтін генетикалық түр емес.'),
question: t('Чем угасание условной реакции отличается от забывания или утомления?', 'How does extinction differ from forgetting or fatigue?', 'Шартты реакцияның сөнуі ұмытудан немесе шаршаудан қалай ерекшеленеді?'),
task: t('Адаптируйте ПЗ 7: составьте план учебного сравнения «сигнал с подкреплением» и «сигнал без подкрепления». Укажите контроль, порядок предъявления и наблюдаемый ответ. По СРО 3–4 объясните, почему нельзя судить о личности или интеллекте по одному результату.', 'Adapt Practical 7 into a comparison of reinforced and unreinforced cues. Specify controls, presentation order and measured response. Explain why one result cannot establish personality or intelligence, linking to ISW 3–4.', 'ПЗ 7-ні «нығайтылған сигнал» және «нығайтусыз сигнал» салыстыруына бейімдеңіз. Бақылауды, көрсету ретін және жауапты белгілеңіз. СРО 3–4 бойынша бір нәтижеден тұлға не интеллект туралы қорытынды шығаруға болмайтынын түсіндіріңіз.'), terms: [t('Условная реакция', 'Conditioned response', 'Шартты реакция'), t('Угасание', 'Extinction', 'Сөну')] },
{ id: 24, sources: ['sleep'], materials: ['ПЗ 7: сон', 'СРО 6', 'СРО 5'],
mechanism: t('Цикл сна и бодрствования зависит от накопления потребности во сне и циркадного управления. Свет через сетчатку сообщает время супрахиазматическим ядрам гипоталамуса. Мелатониновый ритм связан с этой системой, но сон определяется взаимодействием нескольких сетей и сигналов.', 'Sleep-wake timing depends on accumulated sleep pressure and circadian regulation. Retinal light input provides timing information to hypothalamic suprachiasmatic nuclei. Melatonin rhythms relate to this system, but sleep depends on interacting networks and signals.', 'Ұйқы-сергектік циклі ұйқы қажеттілігінің жиналуына және циркадтық реттелуге тәуелді. Жарық торқабық арқылы гипоталамустың супрахиазматикалық ядроларына уақыт туралы ақпарат береді. Ұйқы бірнеше желі мен сигналдың әрекеттесуіне тәуелді.'),
interpretation: t('NREM- и REM-сон различаются сочетаниями ЭЭГ, движений глаз и мышечного тонуса. Один канал ЭЭГ не описывает все признаки стадии. Десинхроноз связан с рассогласованием внутренних ритмов и внешнего расписания; сон не следует объяснять простым выключением коры.', 'NREM and REM sleep differ in EEG, eye movements and muscle tone. One EEG channel does not capture all staging features. Circadian misalignment involves internal rhythms and external schedules; sleep is not simply cortex switching off.', 'NREM және REM ұйқысы ЭЭГ, көз қозғалысы және бұлшықет тонусымен ерекшеленеді. Бір ЭЭГ арнасы кезеңнің барлық белгісін көрсетпейді. Десинхроноз ішкі ырғақ пен сыртқы кестенің сәйкессіздігіне байланысты; ұйқы қыртыстың жай өшуі емес.'),
question: t('Почему сон нельзя объяснить только временем последнего пробуждения?', 'Why can sleep not be explained only by time since waking?', 'Ұйқыны тек соңғы оянудан өткен уақытпен неге түсіндіруге болмайды?'),
task: t('По СРО 6 и ПЗ 7 сравните два режима с одинаковой длительностью сна, но разным временем сна и освещения. Укажите различие циркадного и гомеостатического факторов. Составьте таблицу признаков NREM и REM без медицинской диагностики.', 'Use ISW 6 and Practical 7 to compare schedules with equal sleep duration but different sleep and light timing. Distinguish circadian from homeostatic factors. Tabulate NREM and REM features without medical diagnosis.', 'СРО 6 мен ПЗ 7 бойынша ұзақтығы бірдей, бірақ ұйқы мен жарық уақыты әртүрлі режимдерді салыстырыңыз. Циркадтық және гомеостатикалық факторларды ажыратып, NREM мен REM белгілерінің кестесін жасаңыз.'), terms: [t('Циркадный ритм', 'Circadian rhythm', 'Циркадтық ырғақ'), t('Гомеостатическая потребность во сне', 'Homeostatic sleep pressure', 'Ұйқының гомеостатикалық қажеттілігі')] },
{ id: 25, sources: ['plasticity'], materials: ['Лекция 1: пластичность коры', 'СРО 5: адаптация', 'СРО 4: память'],
mechanism: t('Пластичность включает изменения эффективности синапсов, структуры связей и работы сетей под влиянием активности, опыта и повреждения. Обучение и восстановление используют разные, частично перекрывающиеся механизмы. Изменение поведения не доказывает образование новых нейронов.', 'Plasticity includes changes in synaptic efficacy, connection structure and network operation with activity, experience and injury. Learning and recovery use distinct, partly overlapping mechanisms. Behavioral change does not prove that new neurons formed.', 'Пластикалық өзгерістер белсенділік, тәжірибе және зақым әсерінен синапс тиімділігінің, байланыс құрылымының және желі жұмысының өзгеруін қамтиды. Үйрену мен қалпына келу ішінара ортақ тетіктерді пайдаланады. Мінез-құлық өзгерісі жаңа нейрондар түзілгенін дәлелдемейді.'),
interpretation: t('Улучшение выполнения может отражать восстановление функции, компенсацию другой стратегией или привыкание к заданию. Для различения нужны исходная оценка, повторное измерение и контроль. Пластичность бывает полезной и неблагоприятной; она не гарантирует полного восстановления после поражения.', 'Better performance may reflect functional recovery, compensation using a different strategy or task familiarity. Baseline, repeat measures and controls help distinguish these. Plasticity can be beneficial or maladaptive and does not guarantee complete recovery.', 'Орындаудың жақсаруы қызметтің қалпына келуін, басқа стратегиямен өтелуін немесе тапсырмаға дағдылануды көрсетуі мүмкін. Оларды ажыратуға бастапқы бағалау, қайталама өлшеу және бақылау қажет. Пластикалық өзгеріс пайдалы да, қолайсыз да болуы мүмкін.'),
question: t('Как отличить восстановление функции от компенсации при выполнении задания?', 'How can functional recovery be distinguished from task compensation?', 'Тапсырмада қызметтің қалпына келуін өтемдік стратегиядан қалай ажыратуға болады?'),
task: t('По теме пластичности из лекции 1 предложите исследование изменения навыка: исходное выполнение, тренировка, повторная оценка и перенос на новое задание. Укажите альтернативные объяснения улучшения и какие данные их проверяют.', 'Using the plasticity topic in Lecture 1, design a skill-change study: baseline, practice, repeat assessment and transfer to a new task. Identify alternative explanations for improvement and the data needed to test them.', 'Лекция 1-дегі пластикалық өзгеріс тақырыбы бойынша дағды зерттеуін ұсыныңыз: бастапқы орындау, жаттығу, қайталама бағалау және жаңа тапсырмаға көшіру. Жақсарудың балама түсіндірмелері мен оларды тексеретін деректерді көрсетіңіз.'), terms: [t('Нейропластичность', 'Neuroplasticity', 'Нейропластикалық өзгеріс'), t('Компенсация', 'Compensation', 'Өтемдік бейімделу')] },
];
